import {VEHICLES,ITEMS,euro} from './data.js?v=0.8.0';
import {ownedVehicles,TRUNKS,PREMIUM,usedOffers,resale,atGarage,trunkPoint} from './fleet.js?v=0.8.0';
import {TRANSIT_STOPS,PARKING_SPACES,stopById,parkingById} from './mobility-layout.js?v=0.8.0';
import {tripQuote,canTravel} from './transit.js?v=0.8.0';
import {clockLabel} from './game-time.js?v=0.8.0';
import {inventoryWeight} from './inventory.js?v=0.8.0';
import {inReach} from './interactions.js?v=0.8.0';
export function fleetPanel(s,button,shop=false){
 const vehicles=ownedVehicles(s),here=atGarage(s),cmd=(v,a,text,disabled=false)=>button(text,'fleet',a+'|'+v.uid,'secondary',disabled);
 return `<p class="lead">${vehicles.length} / 6 Fahrzeuge · jedes mit eigenem Standort und Gepäck. Das Stadtrad kostet keinen Kraftstoff und keine Versicherung; Fahrradkorb: 6 kg.</p><div class="cards">${vehicles.map(v=>`<article class="card"><span class="tag">${s.vehicle?.uid===v.uid?'AUSGEWÄHLT':v.stored?'IN DER GARAGE':'IN DER STADT'}</span><h3>${VEHICLES[v.id].name}</h3><p>${Math.floor(v.odometer).toLocaleString('de-DE')} km · Zustand ${Math.round(v.condition)} %<br>${v.id==='bike'?'Muskelkraft':`Tank ${Math.round(v.fuel)} % · ${v.insured?'Versichert':'Nicht versichert'}`}<br>${v.stored?'Eingelagert':parkingById(v.parking)?.name??'Frei abgestellt'}</p><div class="button-row">${v.stored?cmd(v,'retrieve','Bereitstellen',!here):button('Standort zeigen','findFleet',v.uid,'secondary')+cmd(v,'select','Auswählen')}${!v.stored?button(v.id==='bike'?'Fahrradkorb':'Kofferraum','trunk',v.uid,'secondary',!inReach(s.position,trunkPoint(v),'trunk')||s.inside||s.riding):''}${here&&!v.stored?cmd(v,'store','In Garage einlagern'):''}</div>${v.id!=='bike'?cmd(v,'insurance',v.insured?'Versicherung kündigen':'Versichern · '+euro(PREMIUM[v.id])+'/Tag'):''}${here?`<div class="button-row">${cmd(v,'fuel','Tanken · '+euro(Math.ceil((100-v.fuel)*30)),v.stored||v.id==='bike'||v.fuel>=100)}${cmd(v,'repair','Warten · '+euro(Math.max(0,Math.ceil((100-v.condition)*(v.id==='bike'?10:120))-Math.floor(v.claimCredit))),v.stored||v.condition>=100)}${button('Verkaufen · '+euro(resale(v)),'confirmFleetSale',v.uid,'secondary')}</div>`:''}</article>`).join('')}</div>${!vehicles.length?'<div class="info-box">Dein erster Schritt: ein Stadtrad für 125 €. Schnellere Kurierwege ohne laufende Prämien.</div>':''}${shop?`<h3 class="section-title">Neufahrzeuge</h3><div class="cards">${Object.entries(VEHICLES).map(([id,v])=>`<article class="card"><h3>${v.name}</h3><p>${v.description}</p><div class="price">${euro(v.cost)}</div>${button('Kaufen','buyVehicle',id,'primary',!here||vehicles.length>=6||s.money<v.cost)}</article>`).join('')}</div><h3 class="section-title">Gebrauchtwagen · Tag ${s.day}</h3><div class="cards">${usedOffers(s.day).map(v=>`<article class="card"><span class="tag">ZUSTAND OFFENGELEGT</span><h3>${VEHICLES[v.id].name}</h3><p>${v.odometer.toLocaleString('de-DE')} km · Zustand ${v.condition} % · Tank 45 %</p><div class="price">${euro(v.price)}</div>${button(s.usedPurchases?.includes(v.key)?'Heute verkauft':'Gebraucht kaufen','buyUsed',v.key,'primary',!here||s.money<v.price||vehicles.length>=6||s.usedPurchases?.includes(v.key))}</article>`).join('')}</div>`:button('Mobilwerk markieren','navigate','garage','secondary')}<h3 class="section-title">Öffentliche Stellplätze</h3><div class="rows">${PARKING_SPACES.map(p=>`<div class="row"><div><b>${p.name}</b><p>${vehicles.some(v=>v.parking===p.id&&!v.stored)?'Belegt':'Frei'} · kostenlos</p></div>${button('Weg zeigen','findParking',p.id,'secondary')}</div>`).join('')}</div><p class="footnote">P: im Stillstand in einen nahen freien Stellplatz einparken. Service, Einlagern und Verkauf persönlich am Mobilwerk. Versicherung deckt 70 % der Reparaturkosten neuer Unfallschäden, nicht normalen Verschleiß; Folgetagesprämie um Mitternacht. Ohne Bargeld endet der Schutz.</p>`;
}
export function trunkPanel(s,uid,button){const v=ownedVehicles(s).find(v=>v.uid===uid);if(!v)return '<p>Fahrzeug nicht verfügbar.</p>';const limit=TRUNKS[v.id],list=(items,direction)=>items.map((p,i)=>`<div class="row"><div><b>${ITEMS[p.id].name} × ${p.count}</b></div><div class="button-row">${button('1 '+(direction==='deposit'?'einladen':'nehmen'),'trunkTransfer',[uid,direction,i,1].join('|'),'secondary',p.id==='parcel')}${button('Alle','trunkTransfer',[uid,direction,i,p.count].join('|'),'secondary',p.id==='parcel')}</div></div>`).join('');return `<p class="lead">${VEHICLES[v.id].name} · ${inventoryWeight(v.trunk).toFixed(1)} / ${limit.kg} kg · ${v.trunk.length} / ${limit.slots} Plätze</p><div class="storage-layout"><section><h3>Rucksack</h3>${list(s.inventory,'deposit')||'<p>Leer.</p>'}</section><section><h3>${v.id==='bike'?'Fahrradkorb':'Kofferraum'}</h3>${list(v.trunk,'withdraw')||'<p>Leer.</p>'}</section></div><p class="footnote">Nur direkt am stehenden Fahrzeug. Auftragspakete bleiben bei dir.</p>`;}
export function transitPanel(s,id,button){
 const from=stopById(id);if(!from)return `<p class="lead">B1: Westbahnhof, Stadtmitte, Westhafen und Lindenpark. S1: Westbahnhof ↔ Gleishof Süd. Betrieb 06:00–23:00.</p><div class="rows">${TRANSIT_STOPS.map(p=>`<div class="row"><div><b>${p.name}</b><p>${p.mode==='bus'?'B1 · alle 20 Minuten · 1,80 €':'S1 · alle 30 Minuten · 2,40 €'}</p></div>${button('Haltestelle markieren','findStop',p.id,'secondary')}</div>`).join('')}</div>`;
 return `<p class="lead">${from.name} · ${from.mode==='bus'?'B1 · Bus':'S1 · S-Bahn'}<br>06:00–23:00 · ${from.mode==='bus'?'20':'30'}-Minuten-Takt. Fahrrad und Autos bleiben am Abfahrtsort.</p><div class="cards">${TRANSIT_STOPS.filter(p=>p.mode===from.mode&&p.id!==id).map(to=>{const q=tripQuote(s,id,to.id);return `<article class="card"><h3>${to.name}</h3><p>Abfahrt ${clockLabel(q.departure)}${Math.floor(q.departure/1440)>s.day?' · morgen':''}<br>${q.waitLabel} Spielmin. warten + ${q.ride} Spielmin. Fahrt<br>Gesamt ${q.totalLabel} Spielmin. · Hunger, Mieten und Fristen laufen weiter.</p><div class="price">${euro(q.fare)}</div>${button('Ticket kaufen & einsteigen','travel',id+'|'+to.id,'primary',!canTravel(s,from)||s.money<q.fare||q.wait>90)}</article>`;}).join('')}</div><p class="footnote">Die kurze Einstiegssequenz ersetzt die Wartezeit im Bild; berechnet werden genau die angezeigten Spielminuten. Keine zweite Zeitbeschleunigung durch 4×/10×.</p>`;
}
